command:
$ErrorActionPreference = 'Stop'
$workspace = (Get-Location).Path
. "$workspace\.forge-codex\instructions\scripts\Common.ps1"

& "$workspace\.forge-codex\instructions\scripts\Verify-Ledger.ps1" -WorkspaceRoot $workspace

$runStatePath = Join-Path $workspace '.forge-codex/state/run-state.json'
$evidencePath = Join-Path $workspace '.forge-codex/state/evidence/P14/mcp-presence-continuity-status-checkpoint.json'
$null = Get-Content -Raw -LiteralPath $runStatePath | ConvertFrom-Json
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json

$recordPaths = @($evidence.build_command_records) + @($evidence.test_command_records) + @($evidence.diagnostic_command_records)
foreach ($relative in $recordPaths) {
    $recordPath = Join-Path $workspace $relative
    if (-not (Test-Path -LiteralPath $recordPath -PathType Leaf)) {
        throw "Referenced command record is missing: $relative"
    }
    $record = Get-Content -Raw -LiteralPath $recordPath | ConvertFrom-Json
    if ([bool]$record.timed_out) {
        throw "Referenced command record timed out: $relative"
    }
    foreach ($streamProperty in @('stdout', 'stderr')) {
        $streamRelative = [string]$record.$streamProperty
        $streamPath = Join-Path $workspace $streamRelative
        if (-not (Test-Path -LiteralPath $streamPath -PathType Leaf)) {
            throw "Command stream is missing: $streamRelative"
        }
        $actualStreamHash = Get-FileSha256 $streamPath
        $expectedProperty = $streamProperty + '_sha256'
        $expectedStreamHash = [string]$record.$expectedProperty
        if ($actualStreamHash -ne $expectedStreamHash) {
            throw "Command stream hash mismatch: $streamRelative"
        }
    }
}

$finalSuccessRecords = @(
    '.forge-codex/state/commands/20260827T065734188Z-9ae2dbbd.json',
    '.forge-codex/state/commands/20260827T065835912Z-69d028a1.json',
    '.forge-codex/state/commands/20260827T071247018Z-8c3b0969.json',
    '.forge-codex/state/commands/20260827T071307202Z-a122e8a1.json',
    '.forge-codex/state/commands/20260827T071329153Z-7149020f.json'
)
foreach ($relative in $finalSuccessRecords) {
    $record = Get-Content -Raw -LiteralPath (Join-Path $workspace $relative) | ConvertFrom-Json
    if ([int]$record.exit_code -ne 0 -or [bool]$record.timed_out) {
        throw "Final qualifying command did not pass: $relative"
    }
}

foreach ($artifact in $evidence.artifacts) {
    $artifactPath = Join-Path $workspace ([string]$artifact.path)
    if (-not (Test-Path -LiteralPath $artifactPath -PathType Leaf)) {
        throw "Evidence artifact is missing: $($artifact.path)"
    }
    $artifactItem = Get-Item -LiteralPath $artifactPath
    if ($artifactItem.Length -ne [long]$artifact.bytes) {
        throw "Evidence artifact size mismatch: $($artifact.path)"
    }
    $actualArtifactHash = Get-FileSha256 $artifactPath
    if ($actualArtifactHash -ne [string]$artifact.sha256) {
        throw "Evidence artifact hash mismatch: $($artifact.path)"
    }
}

foreach ($source in $evidence.source_evidence) {
    $sourcePath = Join-Path $workspace ([string]$source.path)
    if (-not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) {
        throw "Source-evidence file is missing: $($source.path)"
    }
    $actualSourceHash = Get-FileSha256 $sourcePath
    if ($actualSourceHash -ne [string]$source.sha256) {
        throw "Source-evidence hash mismatch: $($source.path)"
    }
}

& "$workspace\.forge-codex\instructions\scripts\Validate-NoAttribution.ps1" -WorkspaceRoot $workspace
& "$workspace\.forge-codex\instructions\scripts\Validate-NoPython.ps1" -WorkspaceRoot $workspace

& git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed with exit code $LASTEXITCODE."
}

$textPaths = @()
$textPaths += @(git diff --name-only HEAD)
$textPaths += @(git ls-files --others --exclude-standard)
$textPaths = $textPaths |
    Where-Object {
        $_ -and
        (Test-Path -LiteralPath $_ -PathType Leaf) -and
        ($_ -notlike '.forge-codex/state/commands/*') -and
        ($_ -ne '.forge-codex/state/event-ledger.jsonl')
    } |
    Sort-Object -Unique

foreach ($relative in $textPaths) {
    $extension = [System.IO.Path]::GetExtension($relative).ToLowerInvariant()
    if ($relative -ne 'CMakeLists.txt' -and $extension -notin @('.cpp', '.h', '.md', '.json', '.jsonl', '.txt', '.ps1', '.cmake', '.tsv')) {
        continue
    }
    $path = Join-Path $workspace $relative
    $bytes = [System.IO.File]::ReadAllBytes($path)
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) {
        throw "$relative contains a UTF-8 BOM."
    }
    $text = [System.Text.UTF8Encoding]::new($false, $true).GetString($bytes)
    if ([regex]::IsMatch($text, '(?<!\r)\n|\r(?!\n)')) {
        throw "$relative contains a non-CRLF line ending."
    }
}

Write-Host 'P14 presence and status checkpoint integrity validation passed.'
